#!/usr/bin/env node
// Generates platform token files from figma-export.json.
//   node shared/design-tokens/build.mjs          -> writes outputs
//   node shared/design-tokens/build.mjs --check  -> exits 1 if outputs are stale (used in CI)
// Never edit generated files by hand: change Figma, re-export, re-run.
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '../..');
const src = JSON.parse(readFileSync(join(here, 'figma-export.json'), 'utf8'));
const HEADER = 'GENERATED by shared/design-tokens/build.mjs from figma-export.json — do not edit.';

const kebab = (s) => s.replace(/\//g, '-');
const camel = (s) => s.replace(/[\/-]([a-z0-9])/g, (_, c) => c.toUpperCase());
const pct = (v, size) => (typeof v === 'string' && v.endsWith('%') ? (parseFloat(v) / 100) * size : Number(v) || 0);

const primitives = src.collections.Primitives.vars;
const semantic = src.collections.Color.vars;
const sizes = src.collections.Size.vars;
const text = src.text;
const effects = src.effects;

// ---------- CSS variables ----------
function css() {
  const light = [], dark = [], base = [];
  for (const [k, v] of Object.entries(primitives)) base.push(`  --kn-${kebab(k)}: ${v.Value};`);
  for (const [k, v] of Object.entries(semantic)) { light.push(`  --kn-${kebab(k)}: ${v.Light};`); dark.push(`  --kn-${kebab(k)}: ${v.Dark};`); }
  for (const [k, v] of Object.entries(sizes)) base.push(`  --kn-${kebab(k)}: ${v.Value}px;`);
  for (const e of effects) base.push(`  --kn-${kebab(e.name)}: ${e.effects.map((x) => `${x.x}px ${x.y}px ${x.blur}px ${x.spread}px ${x.color}`).join(', ')};`);
  return `/* ${HEADER} */\n:root {\n${base.join('\n')}\n${light.join('\n')}\n  color-scheme: light;\n}\n` +
    `@media (prefers-color-scheme: dark) {\n  :root:not([data-theme="light"]) {\n${dark.map((l) => '  ' + l).join('\n')}\n    color-scheme: dark;\n  }\n}\n` +
    `:root[data-theme="dark"] {\n${dark.join('\n')}\n  color-scheme: dark;\n}\n`;
}

// ---------- Tailwind preset ----------
function tailwind() {
  const colors = {};
  for (const k of Object.keys(semantic)) colors[kebab(k)] = `var(--kn-${kebab(k)})`;
  for (const [k, v] of Object.entries(primitives)) { const [fam, step] = k.split('/'); (colors[fam] ||= {})[step] = v.Value; }
  const spacing = {}, radius = {};
  for (const [k, v] of Object.entries(sizes)) { if (k.startsWith('space/')) spacing[k.split('/')[1]] = `${v.Value}px`; if (k.startsWith('radius/')) radius[k.split('/')[1]] = `${v.Value}px`; }
  const fontSize = {};
  for (const t of text) {
    if (!/^(Web|Latin)\//.test(t.name)) continue;
    const key = t.name.toLowerCase().replace('/', '-');
    fontSize[key] = [`${t.size}px`, { lineHeight: `${t.lineHeight}px`, letterSpacing: `${(pct(t.letterSpacing, 1)).toFixed(3)}em`, fontWeight: t.style === 'Bold' ? '700' : t.style === 'SemiBold' ? '600' : '400' }];
  }
  const boxShadow = {}; for (const e of effects) boxShadow[e.name.split('/')[1]] = `var(--kn-${kebab(e.name)})`;
  // Spacing REPLACES Tailwind's default scale so class numbers equal Figma pixels (p-16 = 16px).
  const preset = { theme: { spacing: { px: '1px', ...spacing }, extend: { colors, borderRadius: radius, fontSize, boxShadow,
    fontFamily: { sans: ['"Noto Sans"', '"Noto Sans Devanagari"', '"Noto Sans Gujarati"', 'system-ui', 'sans-serif'] } } } };
  return `// ${HEADER}\n/** @type {import('tailwindcss').Config} */\nmodule.exports = ${JSON.stringify(preset, null, 2)};\n`;
}

// ---------- Flutter ----------
function dart() {
  const hex = (h) => { const s = h.replace('#', ''); const rgb = s.slice(0, 6); const a = s.length === 8 ? s.slice(6, 8) : 'ff'; return `Color(0x${(a + rgb).toUpperCase()})`; };
  const L = [`// ${HEADER}`, `// ignore_for_file: constant_identifier_names`, `import 'package:flutter/material.dart';`, ''];
  L.push('/// Brand primitives (mode-independent).', 'abstract final class KnPrimitive {');
  for (const [k, v] of Object.entries(primitives)) L.push(`  static const ${camel(k)} = ${hex(v.Value)};`);
  L.push('}', '');
  L.push('/// Semantic colours for one theme mode.', 'final class KnColors {');
  const keys = Object.keys(semantic);
  for (const k of keys) L.push(`  final Color ${camel(k)};`);
  L.push(`  const KnColors({${keys.map((k) => `required this.${camel(k)}`).join(', ')}});`);
  for (const mode of ['Light', 'Dark']) {
    L.push(`  static const ${mode.toLowerCase()} = KnColors(`);
    for (const k of keys) L.push(`    ${camel(k)}: ${hex(semantic[k][mode])},`);
    L.push('  );');
  }
  L.push('}', '');
  L.push('abstract final class KnSize {');
  for (const [k, v] of Object.entries(sizes)) L.push(`  static const double ${camel(k).replace(/^space(\d)/, 'space$1')} = ${Number(v.Value).toFixed(1)};`);
  L.push('}', '');
  L.push('/// Text styles per script. Pick the set with KnText.forLocale(locale).', 'final class KnTextSet {');
  const roles = ['display', 'h1', 'h2', 'h3', 'body-lg', 'body', 'label', 'label-sm', 'caption', 'caption-strong'];
  for (const r of roles) L.push(`  final TextStyle ${camel(r)};`);
  L.push(`  const KnTextSet({${roles.map((r) => `required this.${camel(r)}`).join(', ')}});`);
  L.push('}', '', 'abstract final class KnText {');
  const weight = (s) => (s === 'Bold' ? 'FontWeight.w700' : s === 'SemiBold' ? 'FontWeight.w600' : 'FontWeight.w400');
  for (const script of ['Latin', 'Hindi', 'Gujarati']) {
    L.push(`  static const ${script.toLowerCase()} = KnTextSet(`);
    for (const r of roles) {
      const t = text.find((x) => x.name === `${script}/${r}`);
      L.push(`    ${camel(r)}: TextStyle(fontFamily: '${t.family}', fontSize: ${t.size}, height: ${(t.lineHeight / t.size).toFixed(3)}, letterSpacing: ${pct(t.letterSpacing, t.size).toFixed(2)}, fontWeight: ${weight(t.style)}),`);
    }
    L.push('  );');
  }
  L.push(`  static KnTextSet forLocale(Locale l) => switch (l.languageCode) { 'hi' => hindi, 'gu' => gujarati, _ => latin };`);
  L.push('}', '');
  L.push('abstract final class KnShadow {');
  for (const e of effects) { const x = e.effects[0]; L.push(`  static const ${e.name.split('/')[1]} = [BoxShadow(color: ${hex(x.color)}, offset: Offset(${x.x}, ${x.y}), blurRadius: ${x.blur}, spreadRadius: ${x.spread})];`); }
  L.push('}', '');
  return L.join('\n');
}

const outputs = {
  'shared/design-tokens/dist/tokens.css': css(),
  'shared/design-tokens/dist/tailwind-preset.cjs': tailwind(),
  'mobile/lib/core/theme/kn_tokens.g.dart': dart(),
};
const check = process.argv.includes('--check');
let stale = [];
for (const [rel, body] of Object.entries(outputs)) {
  const p = join(root, rel);
  if (check) { if (!existsSync(p) || readFileSync(p, 'utf8') !== body) stale.push(rel); continue; }
  mkdirSync(dirname(p), { recursive: true }); writeFileSync(p, body); console.log('wrote', rel);
}
if (check && stale.length) { console.error('Stale design tokens, run: node shared/design-tokens/build.mjs\n  ' + stale.join('\n  ')); process.exit(1); }
if (check) console.log('design tokens up to date');
